from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def perim(p):
            x, y = p
            # Bottom edge (excluding (side,0))
            if y == 0 and x < side:
                return x
            # Right edge (excluding (side,side))
            if x == side and y < side:
                return side + y
            # Top edge (excluding (0,side))
            if y == side and x > 0:
                return 2 * side + (side - x)
            # Left edge (excluding (0,0))
            if x == 0 and y > 0:
                return 3 * side + (side - y)
            # The point (0,0) -> 0
            return 0

        pts = sorted(points, key=perim)
        n = len(pts)
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]

        def can(d):
            # Try every starting point
            for s in range(n):
                sx, sy = xs[s], ys[s]
                lx, ly = sx, sy
                cnt = 1
                # Walk clockwise
                for off in range(1, n):
                    j = s + off
                    if j >= n:
                        j -= n
                    if abs(xs[j] - lx) + abs(ys[j] - ly) >= d:
                        cnt += 1
                        lx, ly = xs[j], ys[j]
                        if cnt == k:
                            break
                if cnt == k and abs(sx - lx) + abs(sy - ly) >= d:
                    return True
            return False

        lo, hi = 0, 4 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
